import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import { toggleRootClassName } from "./view";

export { toggleIconClassName, toggleRootClassName } from "./view";

export type ToggleStyle = Readonly<Record<string, string>>;

export type ViewConfig<ParentMessage> = Readonly<{
  pressed: boolean;
  onPressedChange: ParentMessage;
  ariaLabel: string;
  children: readonly Html[];
  value?: string | undefined;
  disabled?: boolean | undefined;
  className?: string | undefined;
  style?: ToggleStyle | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const pressedAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  pressed: boolean
) => [
  h.Attribute("aria-pressed", pressed ? "true" : "false"),
  ...(pressed ? [h.DataAttribute("pressed", "")] : []),
];

export const view = <ParentMessage>({
  pressed,
  onPressedChange,
  ariaLabel,
  children,
  value,
  disabled = false,
  className,
  style,
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.AriaLabel(ariaLabel),
      ...pressedAttributes(h, pressed),
      ...(value === undefined ? [] : [h.Value(value)]),
      ...(disabled ? [h.Disabled(true)] : [h.OnClick(onPressedChange)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(toggleRootClassName, className)),
    ],
    children
  );
};

export const toggleRootClassName =
  "inline-flex h-9 w-9 items-center justify-center rounded-md border border-gray-200 bg-white text-gray-600 shadow-sm transition-colors hover:bg-gray-50 hover:text-gray-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 data-[pressed]:border-accent-200 data-[pressed]:bg-accent-50 data-[pressed]:text-accent-700 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const toggleIconClassName = "h-4 w-4";

import { Schema as S } from "effect";
import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { describe, expect, test } from "vitest";

import * as Toggle from "./index";

const ClickedFavorite = m("ClickedFavorite");
const Message = S.Union([ClickedFavorite]);
type Message = typeof Message.Type;

const favoriteIcon = (): Html => {
  const h = html<Message>();

  return h.span([h.Class(Toggle.toggleIconClassName)], ["♥"]);
};

const view = (pressed: boolean, disabled = false): Html =>
  Toggle.view<Message>({
    pressed,
    disabled,
    ariaLabel: "Favorite",
    value: "favorite",
    onPressedChange: ClickedFavorite(),
    children: [favoriteIcon()],
  });

describe("Toggle registry view", () => {
  test("renders Base UI pressed button semantics and state hook", () => {
    Scene.scene(
      {
        update: (model: boolean, message: Message): readonly [boolean, []] => {
          expect(message._tag).toBe("ClickedFavorite");
          return [!model, []];
        },
        view,
      },
      Scene.with(true),
      Scene.expect(Scene.role("button", { name: "Favorite" })).toHaveAttr(
        "aria-pressed",
        "true"
      ),
      Scene.expect(Scene.role("button", { name: "Favorite" })).toHaveAttr(
        "data-pressed",
        ""
      ),
      Scene.click(Scene.role("button", { name: "Favorite" })),
      Scene.expect(Scene.role("button", { name: "Favorite" })).toHaveAttr(
        "aria-pressed",
        "false"
      ),
      Scene.expect(Scene.role("button", { name: "Favorite" })).not.toHaveAttr(
        "data-pressed"
      )
    );
  });

  test("renders disabled state without click behavior", () => {
    Scene.scene(
      {
        update: (model: boolean): readonly [boolean, []] => [model, []],
        view: (pressed) => view(pressed, true),
      },
      Scene.with(false),
      Scene.expect(Scene.role("button", { name: "Favorite" })).toBeDisabled(),
      Scene.expect(Scene.role("button", { name: "Favorite" })).toHaveAttr(
        "aria-pressed",
        "false"
      )
    );
  });
});
